package page.bento.home

import java.math.BigInteger
import java.security.KeyPairGenerator
import java.security.interfaces.ECPrivateKey
import java.security.interfaces.ECPublicKey
import java.security.spec.ECGenParameterSpec

/**
 * The keys that must MOVE between devices, so cannot live in the Keystore: the account
 * signing key and the two kx keys (identity-android §1). Generated by the platform's own
 * EC code; the private scalar is returned to the caller, who seals it at once.
 */
object SoftKeys {
    class Pair(val scalar: ByteArray, val pub: String) {
        /** Zero the scalar once it is sealed. */
        fun wipe() = scalar.fill(0)
    }

    fun generate(): Pair {
        val kp = KeyPairGenerator.getInstance("EC").apply { initialize(ECGenParameterSpec("secp256r1")) }.generateKeyPair()
        val w = (kp.public as ECPublicKey).w
        return Pair(fixed((kp.private as ECPrivateKey).s), B64u.enc(byteArrayOf(4) + fixed(w.affineX) + fixed(w.affineY)))
    }

    fun fixed(n: BigInteger): ByteArray {
        val b = n.toByteArray()
        return when {
            b.size == 32 -> b
            b.size > 32 -> b.copyOfRange(b.size - 32, b.size)
            else -> ByteArray(32 - b.size) + b
        }
    }
}
